import argparse
import json
from pathlib import Path

from render_client import submit_job


def parse_args():
    p = argparse.ArgumentParser(description="Render all shots of an episode")
    p.add_argument("--episode", required=True, help="episode folder")
    p.add_argument("--only", nargs="*", default=None, help="shot ids to render")
    p.add_argument("--seed", type=int, default=42, help="base seed")
    return p.parse_args()


def load_shots(episode: Path):
    return json.loads((episode / "shots.json").read_text(encoding="utf-8"))


def main():
    args = parse_args()
    episode = Path(args.episode)
    shots = load_shots(episode)
    if args.only:
        shots = [s for s in shots if s["id"] in args.only]
    out_dir = episode / "renders"
    out_dir.mkdir(exist_ok=True)
    for i, shot in enumerate(shots):
        out = out_dir / f"shot_{shot['id']}.png"
        submit_job(shot["prompt"], seed=args.seed + i, output=out)
        print(f"submitted {shot['id']} -> {out}")


if __name__ == "__main__":
    main()
